  const [authBusy,setAuthBusy]=useState(false),[authEmail,setAuthEmail]=useState(""),[authPassword,setAuthPassword]=useState(""),[authError,setAuthError]=useState(""),[authMode,setAuthMode]=useState<"login"|"signup">("login");
